import org.springframework.stereotype.Service;

@Service
public class MovieCatalog {
    private final MovieReader reader;

    public MovieCatalog(MovieReader reader) {
        this.reader = reader;
    }

    public String title(long id) {
        return reader.title(id);
    }
}

interface MovieReader {
    String title(long id);
}

package example.movie;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class MovieApplication {
    public static void main(String[] args) {
        SpringApplication.run(MovieApplication.class, args);
    }
}

import java.util.List;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface MovieRepository extends JpaRepository<Movie, Long> {
    Page<Movie> findByNameContainingIgnoreCase(
        String name, Pageable pageable);

    @Query("select m from Movie m where m.budget >= :min")
    List<Movie> findExpensive(@Param("min") long minimum);
}
